pub fn export_bindings() -> anyhow::Result<()> {
    specta_builder()
        .export(Typescript::default(), BINDINGS_PATH)
        .map_err(|err| anyhow::anyhow!("failed to export IPC bindings: {err}"))
}

/// The hub's program as the user started it. Linux: the routing launcher runs root's copy of it
/// (`router::linux::caps::hub_exe`); the autostart and the next grant name the original.
pub(crate) fn exe() -> std::io::Result<std::path::PathBuf> {
    #[cfg(target_os = "linux")]
    return router::linux::caps::hub_exe();
    #[cfg(not(target_os = "linux"))]
    std::env::current_exe()
}

/// What `main` does with an error from `run`.
pub fn report(err: &anyhow::Error) {
    fatal(&format!("{}\n\n{err:#}", texts::FAILED_TO_START));
}

/// The one native message box: there is no window to show the error in.
#[cfg(windows)]
fn fatal(text: &str) {
    use windows::Win32::UI::WindowsAndMessaging::{MB_ICONERROR, MB_OK, MessageBoxW};
    use windows::core::HSTRING;
    log::error!("{text}");
    // SAFETY: a plain Win32 call with valid, NUL-terminated wide strings.
    let _ = unsafe {
        MessageBoxW(
            None,
            &HSTRING::from(text),
            &HSTRING::from(texts::APP),
            MB_OK | MB_ICONERROR,
        )
    };
}

/// There is no window to show the error in: the journal, the terminal and a notification.
#[cfg(not(windows))]
fn fatal(text: &str) {
    log::error!("{text}");
    eprintln!("{text}");
    notify::send(texts::FAILED_TO_START, text);
}

#[cfg(windows)]
const WEBVIEW2_CLIENT: &str =
    r"Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}";

/// `pv` of the WebView2 Runtime, per machine (WOW6432Node on 64-bit Windows) or per user. An
/// uninstall leaves an empty value or `0.0.0.0` behind.
#[cfg(windows)]
fn webview2_installed() -> bool {
    [
        windows_registry::LOCAL_MACHINE.open(format!(r"SOFTWARE\WOW6432Node\{WEBVIEW2_CLIENT}")),
        windows_registry::CURRENT_USER.open(format!(r"Software\{WEBVIEW2_CLIENT}")),
    ]
    .into_iter()
    .flatten()
    .filter_map(|key| key.get_string("pv").ok())
    .any(|version| !version.trim().is_empty() && version.trim() != "0.0.0.0")
}

pub fn run() -> anyhow::Result<()> {
    // Without the runtime no window can exist: the user is told here (spec 12).
    #[cfg(windows)]
    if !webview2_installed() {
        fatal(texts::WEBVIEW2_MISSING);
        std::process::exit(1);
    }
    let paths = Paths::current()?;
    journal::init(paths.logs());
    log::info!(
        "Zapret Hub {} started from {}, settings {}",
        env!("CARGO_PKG_VERSION"),
        std::env::current_exe().unwrap_or_default().display(),
        paths.settings().display()
    );
    // Read before the settings load: saving them drops the old key (0.8.0 used Flowseal).
    let flowseal = settings::flowseal_dir(&paths.settings());
    let (mut settings, damaged) = settings::load_or_default(&paths.settings());
    // Saved once the move is done (`jobs::startup`): a stop before that keeps the old key in the
    // file, and the next start moves again.
    if let Some(dir) = &flowseal {
        settings::migrate_flowseal(&mut settings, dir);
    }
    // The `tg://proxy` link must survive restarts: a secret is made once and kept.
    if tgws::ensure_secret(&mut settings)
        && flowseal.is_none()
        && let Err(err) = settings::save(&paths.settings(), &settings)
    {
        log::warn!("cannot save the TG WS Proxy secret: {err:#}");
    }
    let state = AppState::new(paths, settings);
    state.migrate_strategies();
    if let Some(text) = damaged {
        state.push_notice(Notice {
            level: NoticeLevel::Error,
            title: texts::SETTINGS_RESET.to_owned(),
            text,
        });
    }
    // The Task Scheduler entry or the autostart desktop entry passes it (autostart.rs).
    let autostarted = std::env::args().any(|arg| arg == "--autostart");
    let builder = specta_builder();
    #[cfg(debug_assertions)]
    if let Err(err) = export_bindings() {
        log::warn!("{err:#}");
    }
    tauri::Builder::default()
        // First: a second copy hands over to this one before anything else starts.
        .plugin(tauri_plugin_single_instance::init(|app, _args, _cwd| {
            window::show(app)
        }))
        .plugin(tauri_plugin_dialog::init())
        .manage(state)
        // Linux: the cross hides the window. Destroying the last one ends GTK's main loop and the
        // tray with it; only «Выход» may end the app (spec 4.2). Windows frees the webview.
        .on_window_event(|window, event| {
            if cfg!(target_os = "linux")
                && let tauri::WindowEvent::CloseRequested { api, .. } = event
            {
                api.prevent_close();
                if let Err(err) = window.hide() {
                    log::warn!("cannot hide the window: {err}");
                }
            }
        })
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            notify::register();
            tray::create(app.handle())?;
            // The router's state or its proxy's kind of state changed; latency alone does not call.
            let handle = app.handle().clone();
            app.state::<AppState>()
                .router
                .on_change(move || actions::changed(&handle));
            let settings = app.state::<AppState>().settings();
            // A logon start stays in the tray once the wizard is done (spec 9.2, 9.3).
            if !(autostarted && settings.start_minimized && settings.wizard_done) {
                window::show(app.handle());
            }
            #[cfg(target_os = "linux")]
            quit_on_signals(app.handle());
            jobs::start(app.handle(), flowseal);
            cli::start(app.handle());
            Ok(())
        })
        .build(tauri::generate_context!())?
        .run(|app, event| match event {
            // The close button leaves the app in the tray; only «Выход» ends it (spec 4.2).
            tauri::RunEvent::ExitRequested {
                code: None, api, ..
            } => api.prevent_exit(),
            tauri::RunEvent::Exit => routing::stop_on_exit(&app.state::<AppState>()),
            _ => {}
        });
    Ok(())
}

/// SIGTERM (logout, `kill`), SIGINT (Ctrl+C) and SIGHUP end the app as «Выход» does, routing
/// stopped first: its table and rules outlive the process. A second Ctrl+C kills at once; a
/// repeated SIGTERM or SIGHUP waits for the routing cleanup only (GDBus raises SIGTERM itself when
/// the session bus closes (`exit-on-close`), and logind sends SIGTERM with SIGHUP, both while a
/// logout's first signal is still clearing the routing): after it they kill at once again, and a
/// quit still running 10 s later (a change waiting for a password prompt) ends the process.
/// How long a quit on a signal may take once the routing is cleared.
#[cfg(target_os = "linux")]
const QUIT_WAIT: std::time::Duration = std::time::Duration::from_secs(10);

#[cfg(target_os = "linux")]
fn quit_on_signals(app: &tauri::AppHandle) {
    use std::sync::atomic::{AtomicI32, Ordering};

    static WRITE: AtomicI32 = AtomicI32::new(-1);
    const SIGNALS: [libc::c_int; 3] = [libc::SIGTERM, libc::SIGINT, libc::SIGHUP];
    extern "C" fn wake(_: libc::c_int) {
        let byte = 0u8;
        // SAFETY: write(2) is async-signal-safe and never blocks here (O_NONBLOCK); the pipe stays
        // open for the process's life; errno is put back for the interrupted code.
        unsafe {
            let errno = *libc::__errno_location();
            libc::write(WRITE.load(Ordering::Relaxed), (&raw const byte).cast(), 1);
            *libc::__errno_location() = errno;
        }
    }

    let mut fds = [0; 2];
    // SAFETY: plain syscalls on a local array and a static handler.
    unsafe {
        if libc::pipe2(fds.as_mut_ptr(), libc::O_CLOEXEC) != 0 {
            log::warn!(
                "cannot watch for signals: {}",
                std::io::Error::last_os_error()
            );
            return;
        }
        libc::fcntl(fds[1], libc::F_SETFL, libc::O_NONBLOCK);
        WRITE.store(fds[1], Ordering::Relaxed);
        let mut action: libc::sigaction = std::mem::zeroed();
        action.sa_sigaction = wake as extern "C" fn(libc::c_int) as libc::sighandler_t;
        for signal in SIGNALS {
            action.sa_flags = libc::SA_RESTART;
            if signal == libc::SIGINT {
                action.sa_flags |= libc::SA_RESETHAND;
            }
            libc::sigaction(signal, &raw const action, std::ptr::null_mut());
        }
    }
    let app = app.clone();
    std::thread::spawn(move || {
        let mut byte = 0u8;
        // SAFETY: reads one byte into a local.
        if unsafe { libc::read(fds[0], (&raw mut byte).cast(), 1) } == 1 {
            // SAFETY: back to the default action.
            unsafe { libc::signal(libc::SIGINT, libc::SIG_DFL) };
            log::info!("quitting on a signal");
            routing::stop_on_exit(&app.state::<AppState>());
            // SAFETY: back to the default actions; nothing left that a kill would leave behind.
            unsafe {
                libc::signal(libc::SIGTERM, libc::SIG_DFL);
                libc::signal(libc::SIGHUP, libc::SIG_DFL);
            }
            std::thread::spawn(|| {
                std::thread::sleep(QUIT_WAIT);
                log::warn!("the quit hung for {} s: exiting", QUIT_WAIT.as_secs());
                std::process::exit(0);
            });
            tray::quit(&app);
        }
    });
}
